using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // GET all shipments (dispatchers only)
        group.MapGet("/", [Authorize(Roles = "Dispatcher")] async (
            ApplicationDbContext db,
            string? status,
            string? destination) =>
        {
            var query = db.Shipments.AsQueryable();

            if (!string.IsNullOrEmpty(status) && Enum.TryParse<Data.ShipmentStatus>(status, true, out var s))
                query = query.Where(x => x.Status == s);

            if (!string.IsNullOrEmpty(destination))
                query = query.Where(x => x.Destination.Contains(destination));

            var shipments = await query.OrderByDescending(x => x.ShippedDate)
                .Select(x => ToDto(x))
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // GET shipment by tracking number (customers)
        group.MapGet("/track/{trackingNumber}", async (
            string trackingNumber,
            ApplicationDbContext db,
            HttpContext httpContext,
            UserManager<ApplicationUser> userManager) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            if (shipment is null)
                return Results.NotFound();

            var user = await userManager.GetUserAsync(httpContext.User);
            var isDispatcher = httpContext.User.IsInRole("Dispatcher");

            // Customers can only see their own shipments
            if (!isDispatcher && shipment.CustomerId != user?.Id)
                return Results.Forbid();

            return Results.Ok(ToDto(shipment));
        });

        // GET shipments for current customer
        group.MapGet("/my", async (
            ApplicationDbContext db,
            HttpContext httpContext,
            UserManager<ApplicationUser> userManager) =>
        {
            var user = await userManager.GetUserAsync(httpContext.User);
            if (user is null) return Results.Unauthorized();

            var shipments = await db.Shipments
                .Where(s => s.CustomerId == user.Id)
                .OrderByDescending(s => s.ShippedDate)
                .Select(s => ToDto(s))
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // POST create shipment (dispatchers only)
        group.MapPost("/", [Authorize(Roles = "Dispatcher")] async (
            ShipmentDto dto,
            ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = dto.TrackingNumber,
                Origin = dto.Origin,
                Destination = dto.Destination,
                Status = (Data.ShipmentStatus)(int)dto.Status,
                ShippedDate = dto.ShippedDate,
                EstimatedDelivery = dto.EstimatedDelivery,
                RecipientName = dto.RecipientName,
                Notes = dto.Notes
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"/api/shipments/track/{shipment.TrackingNumber}", ToDto(shipment));
        });

        // PUT update shipment status (dispatchers only)
        group.MapPut("/{id:int}", [Authorize(Roles = "Dispatcher")] async (
            int id,
            ShipmentDto dto,
            ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = (Data.ShipmentStatus)(int)dto.Status;
            shipment.EstimatedDelivery = dto.EstimatedDelivery;
            shipment.Notes = dto.Notes;
            shipment.Destination = dto.Destination;

            await db.SaveChangesAsync();
            return Results.Ok(ToDto(shipment));
        });
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (Client.Models.ShipmentStatus)(int)s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        RecipientName = s.RecipientName,
        Notes = s.Notes
    };
}

