@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>My Shipments</PageTitle>

<h1>📦 My Shipments</h1>

@if (loading)
{
    <p><em>Loading your shipments...</em></p>
}
else if (shipments is null || shipments.Count == 0)
{
    <div class="alert alert-info">
        <p>You don't have any shipments yet. Use the tracking page to look up a shipment by tracking number.</p>
        <a href="/track" class="btn btn-outline-primary">Track a Shipment</a>
    </div>
}
else
{
    <div class="row">
        @foreach (var shipment in shipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between">
                        <code>@shipment.TrackingNumber</code>
                        <span class="badge @GetStatusBadge(shipment.Status)">@shipment.Status</span>
                    </div>
                    <div class="card-body">
                        <p><strong>From:</strong> @shipment.Origin</p>
                        <p><strong>To:</strong> @shipment.Destination</p>
                        <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                        @if (!string.IsNullOrEmpty(shipment.Notes))
                        {
                            <p class="text-muted"><em>@shipment.Notes</em></p>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private bool loading = true;

    protected override async Task OnInitializedAsync()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments/my");
        loading = false;
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<h1>🔍 Track a Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-001-2026)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@searching">
                @if (searching)
                {
                    <span class="spinner-border spinner-border-sm" role="status"></span>
                }
                else
                {
                    <span>Track</span>
                }
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedNumber</strong>. Please verify the number and try again.
    </div>
}
else if (forbidden)
{
    <div class="alert alert-danger">
        You don't have permission to view this shipment.
    </div>
}
else if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h4 class="mb-0">
                Shipment <code>@shipment.TrackingNumber</code>
                <span class="badge @GetStatusBadge(shipment.Status) ms-2">@shipment.Status</span>
            </h4>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                        <dt>Recipient</dt>
                        <dd>@shipment.RecipientName</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd class="fs-5 fw-bold text-primary">@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</dd>
                    </dl>
                </div>
            </div>
            @if (!string.IsNullOrEmpty(shipment.Notes))
            {
                <div class="alert alert-info mt-3">
                    <strong>Notes:</strong> @shipment.Notes
                </div>
            }

            <!-- Progress indicator -->
            <div class="mt-4">
                <h5>Shipment Progress</h5>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercent(shipment.Status)%"
                         aria-valuenow="@GetProgressPercent(shipment.Status)"
                         aria-valuemin="0"
                         aria-valuemax="100">
                        @shipment.Status
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentDto? shipment;
    private bool searching;
    private bool notFound;
    private bool forbidden;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        searching = true;
        notFound = false;
        forbidden = false;
        shipment = null;
        searchedNumber = trackingNumber.Trim();

        var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(searchedNumber)}");

        if (response.IsSuccessStatusCode)
        {
            shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
        }
        else if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            notFound = true;
        }
        else if (response.StatusCode == System.Net.HttpStatusCode.Forbidden)
        {
            forbidden = true;
        }

        searching = false;
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger progress-bar-striped progress-bar-animated",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 50,
        _ => 0
    };
}

